-----------------------------------------------------------------------------
-- Title      : I2C_minion Testbench: noisy scl
-----------------------------------------------------------------------------
-- File       : I2C_minion_TB_002_noisy_scl.vhd
-- Author     : Peter Samarin <peter.samarin@gmail.com>
