	page1_reg : register_6 port
		map(
			d => data,
			clk => wren and not wraddress(1) and wraddress(0),	-- Write enable on wraddress = "01"
			rst_n => '1',
			q => page1
		);
	page2_reg : register_6 port
		map(
			d => data,
			clk => wren and wraddress(1) and not wraddress(0),	-- Write enable on wraddress = "10"
			rst_n => '1',
