	attribute LOWPWR of spi_sel: signal is "on";

	signal spi_outx : std_logic;
	signal spi_clkx : std_logic;

	-- components

	component Clock is
	  Port (
	   qclk 	: in std_logic;		-- input clock
	   reset	: in std_logic;

	   memclk 	: out std_logic;	-- memory access clock signal
