--- gpsif --------------------------------------------------------------------
subtype gpsif_rw_t is integer range 0 to GPSIF_RW_MAX;
subtype gpsif_wa_t is integer range 0 to GPSIF_WA_MAX;

subtype gpsif_buf_rw_t is integer range 0 to 31;
subtype gpsif_buf_wa_t is integer range 0 to  3;
