    -- write g2sft
    db_i <= write(x"08", x"00000006");
    wait until clk = '1' and clk'event and db_o.ack = '1';
    db_i <= write(x"09", x"0000041c");
    wait until clk = '1' and clk'event and db_o.ack = '1';
    db_i <= write(x"0a", x"0000080b");
    wait until clk = '1' and clk'event and db_o.ack = '1';
    db_i <= write(x"0b", x"00000c64");
    wait until clk = '1' and clk'event and db_o.ack = '1';
