architecture Behavioral of usb_sync_tb is

signal clk, rst, rst_n : std_logic;

signal usb_clk : std_logic;
signal usb_data, usb_txdata : std_logic_vector(7 downto 0) := (others => '0');
signal usb_rd_n, usb_wr_n, usb_oe_n, usb_rxf_n, usb_txe_n : std_logic := '0';

signal read_n, write_n, chipselect : std_logic;
signal readdata, writedata : std_logic_vector(7 downto 0) := (others => '0');

signal tx_full, rx_empty : std_logic;

constant clk_period : time := 25 ns;
constant usb_clk_period : time := 16 ns;

signal bus_read : std_logic_vector(7 downto 0);

begin

chipselect <= '1';
write_n <= '1';
read_n <= '0';
rst_n <= not rst;

txdata_counter : process(usb_clk)
begin
if rising_edge(usb_clk) then
    usb_txdata <= std_logic_vector(unsigned(usb_txdata) + 1);
end if;
end process;


oe_process : process
begin

    wait until usb_clk'event;
    if usb_oe_n = '1' then
        -- Disable output
        wait for 7 ns;
        usb_data <= (others => 'Z');
    else
        wait for 7 ns;
        usb_data <= usb_txdata;
    end if;

end process;

read_process : process
begin

usb_rxf_n <= '1';
wait for 10*usb_clk_period;
wait until rising_edge(usb_clk);
usb_rxf_n <= '0';
wait for 10*usb_clk_period;

end process;

usb_sync : entity work.usb_sync
	Port map(
		clk => clk,
		reset_n => rst_n,
        read_n => read_n,
        write_n => write_n,
        chipselect => chipselect,
        readdata => readdata,
        writedata => writedata,
        tx_full => tx_full,
        rx_empty => rx_empty,
		usb_clock => usb_clk,
		usb_data => usb_data,
		usb_rd_n => usb_rd_n,
		usb_wr_n => usb_wr_n,
		usb_oe_n => usb_oe_n,
		usb_rxf_n => usb_rxf_n,
		usb_txe_n => usb_txe_n
		);

rst_process : process
begin
    rst <= '1';
    wait for clk_period;
    rst <= '0';
    wait;
end process;

-- Clock process definitions
clk_process : process

metadata.right_context:
    clk <= '1';
    wait for clk_period/2;
end process;

usb_clk_process : process
begin
    usb_clk <= '0';
    wait for usb_clk_period/2;
    usb_clk <= '1';
    wait for usb_clk_period/2;
end process;

bus_process : process(clk, rx_empty)

begin

    if rising_edge(clk) then
        if rx_empty = '0' then
            bus_read <= readdata;
        else
            bus_read <= (others => 'U');
        end if;
    end if;

end process;

end Behavioral;

metadata.ground_truth:
           data_a : out STD_LOGIC_VECTOR (15 downto 0);
           data_b : out STD_LOGIC_VECTOR (15 downto 0);
           valid : out STD_LOGIC);
end adc;

metadata.right_context:
constant generate_fir : boolean := true;

signal data_a_buffer, data_b_buffer : std_logic_vector(11 downto 0);

COMPONENT fir_compiler_0
  PORT (
    aclk : IN STD_LOGIC;
    s_axis_data_tvalid : IN STD_LOGIC;
    s_axis_data_tready : OUT STD_LOGIC;
    s_axis_data_tdata : IN STD_LOGIC_VECTOR(31 DOWNTO 0);
    m_axis_data_tvalid : OUT STD_LOGIC;
    m_axis_data_tdata : OUT STD_LOGIC_VECTOR(31 DOWNTO 0)
  );
END COMPONENT;

signal fir_data_in_valid : std_logic := '1';
signal fir_ready : std_logic;
signal fir_data_in, fir_data_out : std_logic_vector(31 downto 0);

signal fir_a, fir_b : std_logic_vector(15 downto 0);

begin

rising : process(clk, adc_data)

begin

if rising_edge(clk) then
    data_a_buffer <= adc_data;
end if;

end process;


falling : process(clk, adc_data)

begin

if falling_edge(clk) then
    data_b_buffer <= adc_data;
end if;

end process;


output : process(clk)
begin

if rising_edge(clk) then
    data_a <= fir_a;
    data_b <= fir_b;
end if;

end process;

fir_data_in <= "0000"&data_a_buffer&"0000"&data_b_buffer;
fir_a <= fir_data_out(31 downto 16);
fir_b <= fir_data_out(15 downto 0);


g_fir : if generate_fir generate
fir : fir_compiler_0
             PORT MAP (
               aclk => clk,
               s_axis_data_tvalid => fir_data_in_valid,
               s_axis_data_tready => fir_ready,
               s_axis_data_tdata => fir_data_in,
               m_axis_data_tvalid => valid,
               m_axis_data_tdata => fir_data_out
             );

end generate;

g_not_fir : if not generate_fir generate

    fir_data_out <= fir_data_in;

    process(clk)
    variable count : unsigned(7 downto 0) := (others => '0');
    begin

        if rising_edge(clk) then
            if count = to_unsigned(40, 8) then
                count := (others => '0');
                valid <= '1';
            else
                count := count + 1;
                valid <= '0';
