           rst : in STD_LOGIC;
           data_a : in STD_LOGIC_VECTOR (15 downto 0);
           data_b : in STD_LOGIC_VECTOR (15 downto 0);
           adc_valid : in STD_LOGIC;
           sample_valid : in STD_LOGIC;
           usb_write : out STD_LOGIC;
           usb_writedata : out STD_LOGIC_VECTOR (7 downto 0);
